from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyFiveMinuteCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_canonical = option.Symbol
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Process the underlying minute bar and generate signals immediately
        # after a complete five-minute bar closes.
        if slice.Bars.ContainsKey(self.spy):
            self._process_spy_minute_bar(slice.Bars[self.spy], slice)

        # Exit and expiration handling occur on every minute Slice.
        self._process_exits(slice)

    def _process_spy_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.Time
        bar_date = local_time.date()

        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        minute = local_time.hour * 60 + local_time.minute
        bucket_minute = minute - ((minute - 570) % 5)
        bucket_start = time(bucket_minute // 60, bucket_minute % 60)

        if (
            self.bucket_date != bar_date
            or self.bucket_start != bucket_start
        ):
            self._finalize_bucket(slice)
            self.bucket_date = bar_date
            self.bucket_start = bucket_start
            self.bucket_bars = []

        # A valid five-minute bar must contain every minute in its interval.
        expected_minute = bucket_minute + len(self.bucket_bars)
        if minute != expected_minute:
            self.bucket_bars = []
            return

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) == 5:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        close = self.bucket_bars[-1].Close
        current_end_minutes = (
            self.bucket_start.hour * 60
            + self.bucket_start.minute
            + 5
        )
        current_end = time(
            current_end_minutes // 60,
            current_end_minutes % 60
        )

        self.closes.append(float(close))

        current_fast = None
        current_slow = None
        if len(self.closes) >= 20:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
            current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        self.bucket_bars = []

        if (
            bullish_cross
            and time(9, 45) <= current_end <= time(14, 30)
        ):
            self._attempt_entry(slice)

    def _attempt_entry(self, slice: Slice):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested or holding.Quantity != 0:
                return

        if not slice.OptionChains:
            self.Debug("Skipped call selection: no option chain.")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)
        chains = list(slice.OptionChains.Values)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        nearest_expiry = min(c.Expiry.date() for c in contracts)
        strike_floor = spy_price * 1.01

        candidates = [
            c for c in contracts
            if c.Expiry.date() == nearest_expiry
            and c.Right == OptionRight.Call
            and c.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible call strike.")
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "SPY bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiry={} strike={}".format(
                selected.Symbol,
                nearest_expiry,
                selected.Strike
            )
        )

    def _process_exits(self, slice: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        today = self.Time.date()

        # Never intentionally carry the option into expiration.
        if today >= expiry_date:
            self.expiration_block_date = today
            self._submit_exit(quantity, "expiration liquidation")
            return

        # Time stop on the trading day immediately preceding expiration.
        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit(quantity, "pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_ticket is not None:
            return

        quote = self._find_current_quote(slice, self.entry_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_exit_order()
            self._submit_exit(quantity, "50 percent profit target")

    def _find_current_quote(self, slice: Slice, symbol: Symbol):
        for chain in list(slice.OptionChains.Values):
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def _submit_exit(self, quantity: int, reason: str):
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.entry_symbol, reason))

    def _cancel_exit_order(self):
        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self.exit_ticket.Cancel("Canceled by profit target.")

    def _previous_trading_day(self, date_value):
        previous = date_value - timedelta(days=1)

        try:
            exchange_hours = self.Securities[self.spy].Exchange.Hours
            previous_dt = exchange_hours.GetPreviousTradingDay(
                DateTime(previous.year, previous.month, previous.day)
            )
            return previous_dt.date()
        except Exception:
            while previous.weekday() >= 5:
                previous -= timedelta(days=1)
            return previous

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == (
            self.entry_ticket.OrderId if self.entry_ticket is not None else -1
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} price={}".format(
                        self.entry_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.Debug("Entry order did not fill: {}".format(
                    self.entry_symbol
                ))
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self.entry_symbol))
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

        order_type_text = str(order_event.OrderType).lower()
        if "exercise" in order_type_text or "assignment" in order_type_text:
            self.Debug(
                "Unexpected option exercise or assignment: {} status={}".format(
                    order_event.Symbol,
                    order_event.Status
                )
            )
